class Car:
    def drive(self):
        return "Car is driving"

class BMW(Car):
    def drive(self):
        return "BMW is driving"

b = BMW()
print(b.drive())

import pytest

@pytest.fixture
def browser():
    print("Setup: Opening browser")
    yield "chrome"
    print("Teardown: Closing browser")

def test_open_page(browser):
    assert browser == "chrome"

def my_decorator(func):
    def wrapper():
        print("Before")
        func()
        print("After")
    return wrapper

@my_decorator
def say_hello():
    print("Hello")

say_hello()

class Device:
    def identify(self):
        return "Generic Device"

class SonyDevice(Device):
    def identify(self):
        return "Sony PlayStation"

ps = SonyDevice()
print(ps.identify())

class Dog:
    def speak(self):
        return "Woof"

class Cat:
    def speak(self):
        return "Meow"

for animal in [Dog(), Cat()]:
    print(animal.speak())

try:
    result = 10 / 0
except ZeroDivisionError:
    print("Cannot divide by zero")
finally:
    print("This always runs")

try:
    result = 10 / 2
except ZeroDivisionError:
    print("Error")
else:
    print(f"Result: {result}")
finally:
    print("Done")
